import XCTest

final class NavTests: XCTestCase {
    func testOpenModeration() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bsky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) {
            openButton.tap()
        }
        sleep(3)

        if bsky.state != .runningForeground {
            bsky.activate()
            sleep(2)
        }

        let moderation = bsky.staticTexts["Moderation"].firstMatch
        let moderationButton = bsky.buttons["Moderation"].firstMatch
        if moderationButton.waitForExistence(timeout: 5) {
            moderationButton.tap()
        } else if moderation.waitForExistence(timeout: 5) {
            moderation.tap()
        }
        sleep(3)
    }
}

